// Independent intelligent-search subsystem; all records below are prototype fixtures.
const aiPages = ['功能概览','搜索主题管理','检索标签管理','主题模板管理','主题发布审核','主题运行统计'];
const aiKeys = ['overview','themes','tags','templates','audit','stats'];
let aiTab='overview', aiKeyword='', aiStatus='', aiRange=7;
const aiObjects=['数据资源','数据产品','业务节点','接入主体'];
const aiThemes=[
 {id:1,name:'区域数据资源综合检索',type:'通用检索',objects:['数据资源','数据产品','业务节点','接入主体'],tags:['公共数据','企业数据'],status:'已发布',desc:'统一发现区域全域数据资源、数据产品及服务主体。',date:'2026-11-04 09:30',calls:12860,coverage:2368},
 {id:2,name:'交通物流行业检索',type:'行业检索',objects:['数据资源','数据产品'],tags:['交通运输'],status:'已发布',desc:'面向交通运行、物流运输场景的行业检索。',date:'2026-11-03 16:20',calls:8420,coverage:856},
 {id:3,name:'普惠金融数据服务',type:'专题检索',objects:['数据产品','接入主体'],tags:['金融服务'],status:'待审核',desc:'支持普惠金融专题的数据产品发现与主体检索。',date:'2026-11-04 10:15',calls:0,coverage:428},
 {id:4,name:'城市治理专题检索',type:'专题检索',objects:['数据资源','业务节点'],tags:['公共数据'],status:'草稿',desc:'城市治理数据资源和业务节点检索。',date:'2026-11-02 14:00',calls:0,coverage:612},
 {id:5,name:'企业经营数据检索',type:'行业检索',objects:['数据资源','数据产品'],tags:['企业数据'],status:'已驳回',desc:'企业经营相关数据资源发现。',date:'2026-11-01 11:30',calls:0,coverage:320}
];
let aiTags=[{id:1,name:'公共数据',parent:'',object:'数据资源',status:'启用',count:1286},{id:2,name:'交通运输',parent:'公共数据',object:'数据资源',status:'启用',count:426},{id:3,name:'金融服务',parent:'',object:'数据产品',status:'启用',count:312},{id:4,name:'企业数据',parent:'',object:'接入主体',status:'启用',count:768},{id:5,name:'历史归档',parent:'',object:'业务节点',status:'停用',count:0}];
let aiTemplates=[{name:'全域资源通用检索',type:'通用检索',desc:'覆盖四类检索对象，快速构建区域统一资源搜索入口。',objects:aiObjects},{name:'交通物流行业检索',type:'行业检索',desc:'聚焦交通运输与物流资源，按行业标签组织搜索范围。',objects:['数据资源','数据产品']},{name:'普惠金融专题检索',type:'专题检索',desc:'面向金融专题，连接数据产品与可信服务主体。',objects:['数据产品','接入主体']}];
let aiHistory=[{name:'区域数据资源综合检索',result:'审核通过',note:'检索范围与标签配置完整，同意发布。',time:'2026-11-04 09:30',person:'李审核'},{name:'企业经营数据检索',result:'审核驳回',note:'请补充行业标签与检索范围说明。',time:'2026-11-01 11:30',person:'李审核'}];
const aiReq=(id)=>req('intelligent.'+id);
const aiBtn=(text,action,id,primary=false)=>`<button class="${primary?'btn primary':'btn'}" ${aiReq(id)} onclick="${action}">${text}</button>`;
const aiLink=(text,action,id)=>`<button class="link" ${aiReq(id)} onclick="${action}">${text}</button>`;
function aiOpen(tab='overview'){section='intelligent';aiTab=tab;aiKeyword='';aiStatus='';render();}
const aiOriginalRender=render;
render=function(){if(section==='intelligent')aiRender();else {aiOriginalRender();if(section==='launch')aiPatchLaunch();}};
names.push('智能服务系统');colors.push(['#76a4ee','#365bd0']);icons.push('<svg viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="2"><rect x="5" y="9" width="24" height="20" rx="5"/><path d="M17 9V3M12 23h10M2 16h3M29 16h3"/><circle cx="12" cy="16" r="1"/><circle cx="22" cy="16" r="1"/></svg>');
// The existing launchpad delegates only the new card to this subsystem.
document.addEventListener('click',e=>{if(e.target.closest('[data-req-id="intelligent.enter"]')){e.stopImmediatePropagation();selectSystem(6);aiOpen();}},true);
function aiPatchLaunch(){const card=document.querySelector('.cards > .card:nth-child(7)');if(card){card.setAttribute('data-req-id','intelligent.enter');card.setAttribute('data-req-element','intelligent.enter');card.removeAttribute('onclick');}}
function aiBadge(s){return `<span class="ai-badge ${s==='已发布'||s==='启用'||s==='审核通过'?'green':s==='待审核'?'orange':s==='已驳回'||s==='审核驳回'?'red':''}">${esc(s)}</span>`;}
function aiRender(){
 const i=aiKeys.indexOf(aiTab);
 $('#sidebar').innerHTML=`<div class="ai-nav-title">智能服务系统</div><div class="nav active"><span>⌕</span>智能搜索<em>⌄</em></div><div class="ai-nav-group">搜索全局配置</div>${aiPages.map((p,j)=>`<button class="ai-nav-item ${i===j?'active':''}" ${aiReq(aiKeys[j])} onclick="aiOpen('${aiKeys[j]}')">${p}${j===4?'<small>'+aiThemes.filter(t=>t.status==='待审核').length+'</small>':''}</button>`).join('')}<button class="ai-back" onclick="section='launch';render()">⇤ 返回快捷入口</button>`;
 $('#main').innerHTML=`<div class="systemtabs"><span onclick="section='launch';render()">首页</span><span class="selected">智能服务系统</span></div><div class="ai-page" data-req-surface="intelligent.${aiTab}" data-req-page="intelligent-${aiTab}" data-req-title="${aiPages[i]}"><div class="crumb">智能服务系统 / 智能搜索 / 搜索全局配置 / ${aiPages[i]}</div><div class="ai-heading"><div><h1>${aiPages[i]}</h1><p>${['统一配置区域全域资源搜索，让数据资源更易发现、精准触达。','管理搜索主题的配置、排序与发布，构建面向不同场景的检索入口。','以层级标签组织全域检索对象，建立统一的多维分类体系。','复用成熟搜索配置，快速构建通用、行业及专题检索主题。','集中处理主题发布申请，审核过程与处理意见全程留痕。','洞察主题调用与资源覆盖情况，持续优化检索服务。'][i]}</p></div><span class="ai-environment">● 原型演示数据</span></div><div id="ai-content"></div></div>`;
 [aiOverview,aiThemeList,aiTagList,aiTemplateList,aiAuditList,aiStats][i]();
}
function aiMetric(label,value,desc){return `<article><span>${label}</span><strong>${value}</strong><small>${desc}</small></article>`;}
function aiOverview(){
 $('#ai-content').innerHTML=`<section class="ai-intro" ${aiReq('overview')}><div><span class="ai-kicker">INTELLIGENT SEARCH</span><h2>连接全域资源，发现数据价值</h2><p>为本区域参与数据流通利用的企业与个人，提供统一的数据资源、数据产品及业务服务检索入口，支撑智能问答与智能咨询。</p>${aiBtn('创建搜索主题 →',"aiOpen('themes');aiThemeForm()",'theme.create',true)}${aiBtn('浏览主题模板',"aiOpen('templates')",'templates')}</div><div class="ai-orbit"><span>资源</span><b>智能搜索</b><span>产品</span><span>主体</span><span>节点</span></div></section><div class="ai-metrics" ${aiReq('overview.statistics')}>${aiMetric('搜索主题',aiThemes.length,'覆盖通用、行业、专题场景')}${aiMetric('已发布主题',aiThemes.filter(x=>x.status==='已发布').length,'审核通过后对外提供检索')}${aiMetric('待审核主题',aiThemes.filter(x=>x.status==='待审核').length,'等待管理员处理')}${aiMetric('启用标签',aiTags.filter(x=>x.status==='启用').length,'支持多维分类与精细化标注')}</div><section class="panel ai-section" ${aiReq('overview')}><h3>配置与使用流程</h3><p class="muted">从资源组织到发布运营，完成搜索主题的全生命周期管理</p><div class="ai-flow">${[['01','建立标签体系','分类标注四类检索对象','tags'],['02','配置搜索主题','从模板创建或自主配置','themes'],['03','提交发布审核','配置检查与审核留痕','audit'],['04','分析运行效果','跟踪调用与对象覆盖','stats']].map(x=>`<button onclick="aiOpen('${x[3]}')"><b>${x[0]}</b><h4>${x[1]}</h4><p>${x[2]}</p><span>前往配置 →</span></button>`).join('')}</div></section><section class="panel ai-section"><h3>管理能力</h3><div class="ai-capabilities">${aiPages.slice(1).map((p,i)=>`<button ${aiReq(aiKeys[i+1])} onclick="aiOpen('${aiKeys[i+1]}')"><b>${p} →</b><p>${['新建、编辑、查询、删除、排序与发布','新增、编辑、停用、层级配置与对象关联','查看、引用、定制与保存模板','审核通过、驳回及审核记录查询','调用量、覆盖数量与使用情况分析'][i]}</p></button>`).join('')}</div></section>`;
}
function aiFilters(statuses,placeholder='请输入名称关键词'){return `<form class="ai-filters" ${aiReq(aiTab+'.query')} onsubmit="event.preventDefault();aiKeyword=this.keyword.value.trim();aiStatus=this.state.value;aiRefresh()"><label>名称 <input name="keyword" maxlength="50" placeholder="${placeholder}" value="${esc(aiKeyword)}"></label><label>状态 / 类型 <select name="state"><option value="">全部</option>${statuses.map(x=>`<option ${x===aiStatus?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn primary">查询</button><button type="button" class="btn" onclick="aiKeyword='';aiStatus='';aiRefresh()">重置</button></form>`;}
function aiRefresh(){({themes:aiThemeList,tags:aiTagList,templates:aiTemplateList,audit:aiAuditList})[aiTab]();}
function aiTable(headers,rows){return `<div class="ai-table"><table><thead><tr>${headers.map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">暂无匹配记录</td></tr>`}</tbody></table></div><div class="pagination">共 ${rows.length} 条　　10条/页　　〈　<b>1</b>　〉</div>`;}
function aiThemeList(){let list=aiThemes.filter(t=>t.name.includes(aiKeyword)&&(!aiStatus||t.status===aiStatus));$('#ai-content').innerHTML=`<section class="panel">${aiFilters(['草稿','待审核','已发布','已驳回'])}</section><section class="panel ai-section"><div class="ai-list-head"><h3>搜索主题 <small>${list.length}</small></h3>${aiBtn('＋ 新建主题','aiThemeForm()','theme.create',true)}</div>${aiTable(['排序','主题名称','主题类型','检索范围','发布状态','更新时间','操作'],list.map(t=>`<tr ${aiReq('theme.manage')}><td>${aiThemes.indexOf(t)+1} ${aiLink('↑',`aiMove(${t.id},-1)`,'theme.sort')} ${aiLink('↓',`aiMove(${t.id},1)`,'theme.sort')}</td><td><b>${esc(t.name)}</b><small class="ai-cell-sub">${esc(t.desc)}</small></td><td>${esc(t.type)}</td><td>${t.objects.join('、')}</td><td>${aiBadge(t.status)}</td><td>${esc(t.date)}</td><td class="ai-actions">${aiLink('查看',`aiThemeForm(${t.id},true)`,'theme.view')}${!['已发布','待审核'].includes(t.status)?aiLink('编辑',`aiThemeForm(${t.id})`,'theme.edit')+aiLink('发布',`aiSubmit(${t.id})`,'theme.publish')+aiLink('删除',`aiDelete(${t.id})`,'theme.delete'):''}</td></tr>`))}</section>`;}
function aiMove(id,d){const i=aiThemes.findIndex(x=>x.id===id);if(i+d<0||i+d>=aiThemes.length)return;[aiThemes[i],aiThemes[i+d]]=[aiThemes[i+d],aiThemes[i]];aiThemeList();toast('主题排序已更新');}
function aiDelete(id){aiConfirm('删除搜索主题','删除后不可恢复，请确认该主题不再使用。',()=>{aiThemes.splice(aiThemes.findIndex(t=>t.id===id),1);aiThemeList();toast('主题已删除');},'theme.delete');}
let aiPending=null;
function aiConfirm(title,text,fn,id){aiPending=fn;aiModal(title,`<p>${esc(text)}</p>`,`<button class="btn primary" ${aiReq(id)} onclick="const fn=aiPending;aiClose();fn()">确认</button>`);}
function aiModal(title,body,footer=''){ $('#overlay').innerHTML=`<div class="veil"><section class="modal ai-modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" data-req-surface="intelligent.dialog"><div class="modalhead">${title}<button class="close" aria-label="关闭" onclick="aiClose()">×</button></div><div class="modalbody">${body}</div><div class="modalfoot"><button class="btn" onclick="aiClose()">关闭</button>${footer}</div></section></div>`;}
function aiClose(){$('#overlay').innerHTML='';}
function aiOptions(list,value){return list.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');}
function aiThemeForm(id=null,readonly=false,templateIndex=null){const t=aiThemes.find(x=>x.id===id)||{};const tpl=templateIndex!==null?aiTemplates[templateIndex]:null;const v=tpl?{...tpl,name:tpl.name+'（副本）'}:t;
 aiModal(readonly?'搜索主题详情':id?'编辑搜索主题':'新建搜索主题',`<form id="ai-theme-form" ${aiReq('theme.form')} onsubmit="aiSaveTheme(event,${id})"><fieldset ${readonly?'disabled':''}><label>主题名称 <i>*</i><input name="name" required maxlength="50" value="${esc(v.name||'')}" placeholder="2—50个字符，名称不可重复" minlength="2"></label><label>主题类型 <i>*</i><select name="type">${aiOptions(['通用检索','行业检索','专题检索'],v.type)}</select></label><label>主题说明 <i>*</i><textarea name="desc" required maxlength="300" placeholder="描述主题定位与使用场景">${esc(v.desc||'')}</textarea></label><label>检索对象 <i>*</i><div class="ai-checks">${aiObjects.map(o=>`<label><input type="checkbox" name="objects" value="${o}" ${(v.objects||['数据资源']).includes(o)?'checked':''}>${o}</label>`).join('')}</div></label><label>关联标签<div class="ai-checks">${aiTags.filter(x=>x.status==='启用'||(v.tags||[]).includes(x.name)).map(x=>`<label><input type="checkbox" name="tags" value="${esc(x.name)}" ${(v.tags||[]).includes(x.name)?'checked':''}>${esc(x.name)}</label>`).join('')}</div></label><div class="notice">保存为草稿后可提交发布审核；审核通过后主题生效。已发布与待审核主题仅支持查看。</div></fieldset></form>`,readonly?'':`<button class="btn primary" form="ai-theme-form" ${aiReq('theme.save')}>保存草稿</button>`);}
function aiSaveTheme(e,id){e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),objects=f.getAll('objects');if(name.length<2||!objects.length||!f.get('desc').trim())return toast('请填写完整说明、有效名称，并选择至少一个检索对象');if(aiThemes.some(x=>x.id!==id&&x.name===name))return toast('主题名称已存在');const t={id:id||Date.now(),name,type:f.get('type'),desc:f.get('desc').trim(),objects,tags:f.getAll('tags'),status:'草稿',date:'2026-11-04 14:30',calls:0,coverage:0};if(id)Object.assign(aiThemes.find(x=>x.id===id),t);else aiThemes.push(t);aiClose();aiThemeList();toast('主题草稿已保存');}
function aiSubmit(id){aiConfirm('提交发布审核','提交后配置将被锁定，审核通过后发布。',()=>{const t=aiThemes.find(x=>x.id===id);t.status='待审核';aiHistory.unshift({name:t.name,result:'提交审核',note:'提交主题配置，等待审核。',person:'当前管理员',time:'2026-11-04 14:30'});aiThemeList();toast('已提交发布审核');},'theme.publish');}
function aiTagList(){let list=aiTags.filter(t=>t.name.includes(aiKeyword)&&(!aiStatus||t.status===aiStatus));$('#ai-content').innerHTML=`<section class="panel">${aiFilters(['启用','停用'])}</section><section class="panel ai-section"><div class="ai-list-head"><h3>检索标签体系</h3>${aiBtn('＋ 新增标签','aiTagForm()','tag.create',true)}</div><div class="notice">标签支持父子层级；停用后不可用于新配置，已有主题关联保留。父标签停用前须先处理启用中的子标签。</div>${aiTable(['标签名称 / 层级','适用对象','关联对象数','状态','操作'],list.map(t=>`<tr ${aiReq('tag.manage')}><td>${t.parent?'<span class="muted">'+esc(t.parent)+' / </span>':''}<b>${esc(t.name)}</b></td><td>${t.object}</td><td>${t.count}</td><td>${aiBadge(t.status)}</td><td>${aiLink('编辑',`aiTagForm(${t.id})`,'tag.edit')}${aiLink('关联对象',`aiTagObjects(${t.id})`,'tag.associate')}${aiLink(t.status==='启用'?'停用':'启用',`aiTagToggle(${t.id})`,'tag.toggle')}</td></tr>`))}</section>`;}
function aiTagForm(id=null){const t=aiTags.find(t=>t.id===id)||{};const descendants=new Set([t.name]);let oldSize;do{oldSize=descendants.size;aiTags.forEach(x=>{if(descendants.has(x.parent))descendants.add(x.name);});}while(oldSize!==descendants.size);
 aiModal(id?'编辑标签':'新增标签',`<form id="ai-tag-form" ${aiReq('tag.form')} onsubmit="aiSaveTag(event,${id})"><fieldset><label>标签名称 <i>*</i><input name="name" required maxlength="20" value="${esc(t.name||'')}"></label><label>父级标签<select name="parent"><option value="">无（一级标签）</option>${aiOptions(aiTags.filter(x=>x.status==='启用'&&!descendants.has(x.name)).map(x=>x.name),t.parent)}</select></label><label>适用对象 <i>*</i><select name="object">${aiOptions(aiObjects,t.object)}</select></label></fieldset></form>`,`<button class="btn primary" form="ai-tag-form" ${aiReq('tag.save')}>保存</button>`);}
function aiSaveTag(e,id){e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return toast('标签名称不能为空');if(aiTags.some(x=>x.id!==id&&x.name===name))return toast('标签名称不可重复');const t=aiTags.find(x=>x.id===id);if(t){const old=t.name;aiTags.forEach(x=>{if(x.parent===old)x.parent=name;});aiThemes.forEach(x=>x.tags=x.tags.map(v=>v===old?name:v));Object.assign(t,{name,parent:f.get('parent'),object:f.get('object')});}else aiTags.push({id:Date.now(),name,parent:f.get('parent'),object:f.get('object'),status:'启用',count:0});aiClose();aiTagList();toast('标签已保存');}
function aiTagToggle(id){const t=aiTags.find(x=>x.id===id);if(t.status==='启用'&&aiTags.some(x=>x.parent===t.name&&x.status==='启用'))return toast('请先停用启用中的子标签');if(t.status==='停用'&&t.parent&&aiTags.find(x=>x.name===t.parent)?.status==='停用')return toast('请先启用父标签');aiConfirm(t.status==='启用'?'停用标签':'启用标签','确认更新该标签的使用状态？',()=>{t.status=t.status==='启用'?'停用':'启用';aiTagList();toast('标签状态已更新');},'tag.toggle');}
const aiAssociations={};
function aiTagObjects(id){const t=aiTags.find(x=>x.id===id);const options=[t.object+'示例 A',t.object+'示例 B',t.object+'示例 C'];const selected=aiAssociations[id]||[];aiModal('关联检索对象 · '+t.name,`<p class="muted">适用对象：${t.object}；以下为原型样例对象，保存后更新关联数量。</p><form id="ai-association" ${aiReq('tag.associate')} onsubmit="event.preventDefault();aiAssociations[${id}]=new FormData(this).getAll('objects');aiTags.find(x=>x.id===${id}).count=aiAssociations[${id}].length;aiClose();aiTagList();toast('对象关联已保存')"><div class="ai-checks">${options.map(o=>`<label><input type="checkbox" name="objects" value="${o}" ${selected.includes(o)?'checked':''}>${o}</label>`).join('')}</div></form>`,`<button class="btn primary" form="ai-association" ${aiReq('tag.associate')}>保存关联</button>`);}
function aiTemplateList(){const list=aiTemplates.map((t,i)=>({...t,index:i})).filter(t=>t.name.includes(aiKeyword)&&(!aiStatus||t.type===aiStatus));$('#ai-content').innerHTML=`<section class="panel">${aiFilters(['通用检索','行业检索','专题检索'])}</section><div class="ai-template-grid">${list.map(t=>`<section class="panel ai-template" ${aiReq('template.manage')}><div class="ai-template-icon">⌕</div><span class="ai-badge">${t.type}</span><h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p><small>检索范围：${t.objects.join('、')}</small><footer>${aiLink('查看详情',`aiTemplateDetail(${t.index})`,'template.view')}${aiBtn('引用模板',`aiUseTemplate(${t.index})`,'template.use',true)}</footer></section>`).join('')||'<section class="panel empty">暂无匹配模板</section>'}</div>`;}
function aiUseTemplate(i){aiOpen('themes');aiThemeForm(null,false,i);}
function aiTemplateDetail(i){const t=aiTemplates[i];aiModal('主题模板详情',`<h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p><p>类型：${t.type}</p><p>检索对象：${t.objects.join('、')}</p><form id="ai-template-custom" ${aiReq('template.customize')} onsubmit="event.preventDefault();const n=this.name.value.trim();if(!n)return toast('请输入模板名称');if(aiTemplates.some(x=>x.name===n))return toast('模板名称已存在');const f=new FormData(this);const objects=f.getAll('objects');if(!objects.length)return toast('请选择至少一个检索对象');if(!f.get('desc').trim())return toast('模板说明不能为空');aiTemplates.push({name:n,type:f.get('type'),desc:f.get('desc').trim(),objects});aiClose();aiTemplateList();toast('自定义模板已保存')"><fieldset><label>另存为自定义模板 <input name="name" required maxlength="50" placeholder="请输入新的模板名称"></label><label>主题类型<select name="type">${aiOptions(['通用检索','行业检索','专题检索'],t.type)}</select></label><label>模板说明<textarea name="desc" required maxlength="300">${esc(t.desc)}</textarea></label><label>检索对象<div class="ai-checks">${aiObjects.map(o=>`<label><input name="objects" type="checkbox" value="${o}" ${t.objects.includes(o)?'checked':''}>${o}</label>`).join('')}</div></label></fieldset></form>`,`<button class="btn" form="ai-template-custom" ${aiReq('template.save')}>保存为模板</button>${aiBtn('引用并定制',`aiClose();aiUseTemplate(${i})`,'template.use',true)}`);}
function aiAuditList(){const pending=aiThemes.filter(x=>x.status==='待审核'&&x.name.includes(aiKeyword));const history=aiHistory.filter(x=>x.name.includes(aiKeyword)&&(!aiStatus||x.result===aiStatus));$('#ai-content').innerHTML=`<section class="panel">${aiFilters(['提交审核','审核通过','审核驳回'])}</section><section class="panel ai-section"><div class="ai-list-head"><h3>待审核申请 <small>${pending.length}</small></h3><span class="muted">通过即发布，驳回后可修改并重新提交</span></div>${aiTable(['主题名称','主题类型','检索范围','提交时间','操作'],pending.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${t.type}</td><td>${t.objects.join('、')}</td><td>${t.date}</td><td>${aiLink('审核',`aiReview(${t.id})`,'audit.review')}</td></tr>`))}</section><section class="panel ai-section" ${aiReq('audit.history')}><h3>审核记录</h3>${aiTable(['主题名称','处理结果','审核意见','处理人','处理时间'],history.map(x=>`<tr><td>${esc(x.name)}</td><td>${aiBadge(x.result)}</td><td>${esc(x.note)}</td><td>${esc(x.person)}</td><td>${x.time}</td></tr>`))}</section>`;}
function aiReview(id){const t=aiThemes.find(x=>x.id===id);aiModal('审核搜索主题',`<h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p><p>检索范围：${t.objects.join('、')}</p><p>关联标签：${t.tags.map(esc).join('、')||'无'}</p><form id="ai-review" ${aiReq('audit.review')} onsubmit="aiReviewSave(event,${id})"><fieldset><label>审核结果<select name="result"><option>审核通过</option><option>审核驳回</option></select></label><label>审核意见 <i>*</i><textarea required name="note" maxlength="300" placeholder="请输入审核依据，驳回时说明修改建议"></textarea></label></fieldset></form>`,`<button class="btn primary" form="ai-review" ${aiReq('audit.submit')}>确认审核</button>`);}
function aiReviewSave(e,id){e.preventDefault();const f=new FormData(e.target);if(!f.get('note').trim())return toast('请填写审核意见');const t=aiThemes.find(x=>x.id===id);t.status=f.get('result')==='审核通过'?'已发布':'已驳回';aiHistory.unshift({name:t.name,result:f.get('result'),note:f.get('note').trim(),person:'当前审核员',time:'2026-11-04 14:30'});aiClose();aiAuditList();toast(t.status==='已发布'?'审核通过，主题已发布':'已驳回，已记录审核意见');}
function aiStats(){const published=aiThemes.filter(x=>x.status==='已发布');const factor=aiRange===7?1:3.6;const total=Math.round(published.reduce((s,x)=>s+x.calls,0)*factor);$('#ai-content').innerHTML=`<section class="panel ai-stats-toolbar" ${aiReq('stats.query')}><b>统计范围</b><select onchange="aiRange=Number(this.value);aiStats()"><option value="7" ${aiRange===7?'selected':''}>近7日</option><option value="30" ${aiRange===30?'selected':''}>近30日</option></select><span class="muted">截至 2026-11-04 · 演示数据</span>${aiBtn('↻ 刷新','aiStats();toast(\'演示统计已刷新\')','stats.refresh')}</section><div class="ai-metrics" ${aiReq('stats.metrics')}>${aiMetric('主题调用量',total.toLocaleString(),'所选周期内检索请求次数')}${aiMetric('覆盖对象数','2,840','已发布主题关联对象去重')}${aiMetric('使用中主题',published.length,'当前发布状态为已发布')}${aiMetric('检索成功率','99.2%','成功响应请求 / 全部请求')}</div><div class="ai-charts" ${aiReq('stats.chart')}><section class="panel ai-section"><h3>主题调用趋势 <small>单位：次</small></h3><div class="ai-chart">${[65,82,73,93,78,87,100].map((v,i)=>`<div><span>${Math.round(total*v/578).toLocaleString()}</span><i style="height:${v*1.5}px"></i><small>${aiRange===7?(i<3?'10/'+(29+i):'11/'+(i-2)):'第'+(i+1)+'时段'}</small></div>`).join('')}</div><p class="muted">${aiRange===7?'10月29日至11月4日，按日统计':'10月6日至11月4日，按时段汇总'} · 含成功与失败调用</p></section><section class="panel ai-section"><h3>覆盖对象分布</h3>${[['数据资源',1680,59],['数据产品',756,27],['业务节点',148,5],['接入主体',256,9]].map(x=>`<div class="ai-distribution"><span>${x[0]}</span><b>${x[1].toLocaleString()}</b><div><i style="width:${x[2]}%"></i></div></div>`).join('')}</section></div><section class="panel ai-section" ${aiReq('stats.ranking')}><h3>主题使用分析</h3>${aiTable(['排名','主题名称','调用量','覆盖对象','状态'],published.sort((a,b)=>b.calls-a.calls).map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}</td><td>${Math.round(t.calls*factor).toLocaleString()}</td><td>${t.coverage.toLocaleString()}</td><td>${aiBadge(t.status)}</td></tr>`))}<div class="notice">统计口径：调用量按请求计数（含失败），覆盖对象按对象ID去重，各主题覆盖数可交叉；统计范围为当前区域已发布主题。正式系统每日更新，手动刷新读取最新聚合结果。</div></section>`;}
if(new URLSearchParams(location.search).get('system')==='intelligent')aiOpen(aiKeys.includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'overview');else if(section==='launch')render();
